import { BaseComponent } from "../../utils/baseElement";
import { Cell } from "../Cell/Cell";
import styles from "./GameBoard.module.scss";

class GameBoard extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   * @param {number} width
   * @param {number} height
   */
  constructor(templateManager, cellController) {
    super({ tag: "section", className: styles.gameBoard });
    this.templateManager = templateManager;
    this.cellController = cellController;
    this.updateGameBoard();

    this.templateManager.onTemplateChange(() => this.updateGameBoard());
  }

  addCells() {
    const cells = [];
    for (let y = 0; y < this.width; y++) {
      for (let x = 0; x < this.width; x++) {
        const cell = new Cell();
        this.addCellEventListeners(cell, x, y);
        this.append(cell);
        cells.push(cell);
      }
    }
  }

  addCellEventListeners(cell, x, y) {
    cell.onRightClick(() => {
      this.cellController.onClick(cell.getNode(), x, y);
    });

    cell.onLeftClick(() => {
      this.cellController.onClick(cell.getNode(), x, y);
    });
  }
  updateGameBoard() {
    this.destroyChildren();
    this.removeClass(styles.easy);
    this.removeClass(styles.medium);
    this.removeClass(styles.hard);

    const template = this.templateManager.getSelectedTemplate();
    if (template) {
      this.width = template.size;
      this.cellController.setTemplate(template);
      this.addClass(styles[template.difficulty]);
      this.addCells();
      // TODO добавить обновление подсказок
    } else {
      this.width = 5;
      this.addClass(styles.easy);
      this.addCells();
    }
  }
}

export { GameBoard }; // main
